int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string w;
    cin >> w;
    int n = w.size();

    // Precompute divisors for each length
    vector<vector<int>> divisors(n + 1);
    for (int len = 1; len <= n; ++len) {
        for (int d = 1; d * d <= len; ++d) {
            if (len % d == 0) {
                divisors[len].push_back(d);
                if (d * d != len) divisors[len].push_back(len / d);
            }
        }
        sort(divisors[len].begin(), divisors[len].end());
    }

    // Check if substring s[l..r] is good
    auto isGood = [&](int l, int r) -> bool {
        int len = r - l + 1;
        for (int d : divisors[len]) {
            if (d == len) continue;
            int k = len / d;
            bool match = true;
            for (int i = 0; i < d && match; ++i) {
                char c = w[l + i];
                for (int j = 1; j < k; ++j) {
                    if (w[l + i + j * d] != c) {
                        match = false;
                        break;
                    }
                }
            }
            if (match) return false; // can be written as k copies
        }
        return true;
    };

    // dp[i] = {min parts, count} for prefix ending at i (1-based)
    vector<pair<int, long long>> dp(n + 1, {INT_MAX / 2, 0});
    dp[0] = {0, 1};
    const long long MOD = 1e9 + 7;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (isGood(j, i - 1)) {
                int newParts = dp[j].first + 1;
                if (newParts < dp[i].first) {
                    dp[i] = {newParts, dp[j].second};
                } else if (newParts == dp[i].first) {
                    dp[i].second = (dp[i].second + dp[j].second) % MOD;
                }
            }
        }
    }

    cout << dp[n].first << "\n" << dp[n].second << "\n";
    return 0;
}

bool isPrimitive(const string& w, int start, int len) {
