        if (len % d == 0) {
            // check if w[start..start+len-1] = w[start..start+d-1] repeated (len/d) times
            bool ok = true;
            for (int i = 0; i < len && ok; i++) {
                if (w[start + i] != w[start + (i % d)]) ok = false;
            }
            if (ok) return false;
        }
    }
    return true;
