/*
We need:
- Minimum number of "good" strings whose concatenation is w
- Number of distinct such minimum representations

A string is good iff it is primitive, i.e. not equal to t^k for k>=2.

Observation:
Any single character is primitive, so answer always exists.

DP:
dp[i] = minimum number of good pieces to represent prefix w[0..i-1]
cnt[i] = number of ways to achieve dp[i]

Transition:
For every j < i, if substring w[j..i-1] is primitive:
    candidate = dp[j] + 1
    update dp[i], cnt[i]

So we need to test primitiveness of all substrings efficiently enough.

A substring s of length L is non-primitive iff it has a period p where p | L and p < L.
Equivalent: minimal period < L.

For each starting position l, build prefix-function on suffix w[l..n-1].
Then for every length len:
    pi = prefix_function value at len-1
    period = len - pi
    substring is non-primitive iff len % period == 0 and period < len
This works for the substring starting at l of length len.

Complexity: O(n^2) time, O(n^2) primitive table avoided by processing suffixes.
We store good[l][r] as bool matrix O(n^2), acceptable for moderate n.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string w;
    if (!(cin >> w)) return 0;
    int n = (int)w.size();

    vector<vector<char>> good(n, vector<char>(n + 1, 0));
    // good[l][len] = whether substring w[l..l+len-1] is primitive

    for (int l = 0; l < n; ++l) {
        int m = n - l;
        vector<int> pi(m, 0);
        for (int i = 1; i < m; ++i) {
            int j = pi[i - 1];
            while (j > 0 && w[l + i] != w[l + j]) j = pi[j - 1];
            if (w[l + i] == w[l + j]) ++j;
            pi[i] = j;

            int len = i + 1;
            int period = len - pi[i];
            bool primitive = !(len % period == 0 && period < len);
            good[l][len] = primitive;
        }
        good[l][1] = 1;
    }

    const int INF = 1e9;
    vector<int> dp(n + 1, INF);
    vector<unsigned long long> cnt(n + 1, 0);

    dp[0] = 0;
    cnt[0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            int len = i - j;
            if (good[j][len]) {
                int cand = dp[j] + 1;
                if (cand < dp[i]) {
                    dp[i] = cand;
                    cnt[i] = cnt[j];
                } else if (cand == dp[i]) {
                    cnt[i] += cnt[j];
                }
            }
        }
    }

    cout << dp[n] << " " << cnt[n] << '\n';
    return 0;
}

