import java.io.*;
import java.util.*;

public class Main {
    static final long MOD1 = 1_000_000_007L;
    static final long MOD2 = 1_000_000_009L;
    static final long BASE1 = 911382323L;
    static final long BASE2 = 972663749L;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && Character.isWhitespace(c));
            if (c == -1) return null;
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static String s;
    static int n;

    static long[] pow1, pow2, pref1, pref2;
    static int[] pi;
    static boolean[] good;

    static long getHash1(int l, int r) {
        long res = (pref1[r] - pref1[l] * pow1[r - l]) % MOD1;
        if (res < 0) res += MOD1;
        return res;
    }

    static long getHash2(int l, int r) {
        long res = (pref2[r] - pref2[l] * pow2[r - l]) % MOD2;
        if (res < 0) res += MOD2;
        return res;
    }

    static boolean equalSub(int l1, int r1, int l2, int r2) {
        return getHash1(l1, r1) == getHash1(l2, r2) &&
               getHash2(l1, r1) == getHash2(l2, r2);
    }

    static void buildPrefixFunction() {
        pi = new int[n];
        for (int i = 1; i < n; i++) {
            int j = pi[i - 1];
            while (j > 0 && s.charAt(i) != s.charAt(j)) j = pi[j - 1];
            if (s.charAt(i) == s.charAt(j)) j++;
            pi[i] = j;
        }
    }

    static void buildHashes() {
        pow1 = new long[n + 1];
        pow2 = new long[n + 1];
        pref1 = new long[n + 1];
        pref2 = new long[n + 1];

        pow1[0] = 1;
        pow2[0] = 1;
        for (int i = 0; i < n; i++) {
            pow1[i + 1] = (pow1[i] * BASE1) % MOD1;
            pow2[i + 1] = (pow2[i] * BASE2) % MOD2;
            pref1[i + 1] = (pref1[i] * BASE1 + s.charAt(i)) % MOD1;
            pref2[i + 1] = (pref2[i] * BASE2 + s.charAt(i)) % MOD2;
        }
    }

    static void buildGood() {
        good = new boolean[n + 1];
        for (int len = 1; len <= n; len++) {
            int p = len - pi[len - 1];
            good[len] = !(len % p == 0 && len / p >= 2);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        s = fs.next();
        if (s == null) return;
        n = s.length();

        buildPrefixFunction();
        buildHashes();
        buildGood();

        int[] dp = new int[n + 1];
        long[] ways = new long[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE / 2);
        dp[0] = 0;
        ways[0] = 1;

        for (int i = 0; i < n; i++) {
            if (dp[i] >= Integer.MAX_VALUE / 4) continue;
            for (int len = 1; i + len <= n; len++) {
                if (!good[len]) continue;
                if (!equalSub(0, len, i, i + len)) continue;

                int ni = i + len;
                if (dp[i] + 1 < dp[ni]) {
                    dp[ni] = dp[i] + 1;
                    ways[ni] = ways[i];
                } else if (dp[i] + 1 == dp[ni]) {
                    ways[ni] += ways[i];
                }
            }
        }

        System.out.println(dp[n] + " " + ways[n]);
    }
}

