        memcpy(w, buffer, n + 1);
    }

    int n = (int)strlen(w);

    /* prefix-function for every suffix:
       pi[s][len-1] = prefix function of substring w[s .. s+len-1]
    */
    int **pi = (int**)malloc(n * sizeof(int*));
    for (int s = 0; s < n; s++) {
        int m = n - s;
        pi[s] = (int*)malloc(m * sizeof(int));
        pi[s][0] = 0;
        for (int i = 1; i < m; i++) {
            int j = pi[s][i - 1];
            while (j > 0 && w[s + i] != w[s + j]) j = pi[s][j - 1];
            if (w[s + i] == w[s + j]) j++;
            pi[s][i] = j;
        }
    }

    /* good[s][e] = 1 if w[s..e] is primitive (good), else 0 */
    char **good = (char**)malloc(n * sizeof(char*));
    for (int s = 0; s < n; s++) {
        good[s] = (char*)malloc(n * sizeof(char));
        for (int e = 0; e < n; e++) good[s][e] = 0;
        for (int e = s; e < n; e++) {
            int len = e - s + 1;
            int p = pi[s][len - 1];
            int period = len - p;
            if (p > 0 && len % period == 0) good[s][e] = 0; /* not primitive */
            else good[s][e] = 1;
        }
    }

    /* DP:
       dp[i] = minimum number of good strings to represent prefix w[0..i-1]
       ways[i] = number of such optimal representations
    */
    int *dp = (int*)malloc((n + 1) * sizeof(int));
    long long *ways = (long long*)malloc((n + 1) * sizeof(long long));

    const int INF = 1e9;
    for (int i = 0; i <= n; i++) {
        dp[i] = INF;
        ways[i] = 0;
    }
    dp[0] = 0;
    ways[0] = 1;

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < i; j++) {
            if (good[j][i - 1]) {
                int cand = dp[j] + 1;
                if (cand < dp[i]) {
                    dp[i] = cand;
                    ways[i] = ways[j];
                } else if (cand == dp[i]) {
                    ways[i] += ways[j];
                    if (ways[i] >= MOD) ways[i] %= MOD;
                }
            }
        }
