import sys

MOD = 10**9 + 7

def prefix_function(s: str):
    n = len(s)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return pi

def is_good_string(s: str) -> bool:
    n = len(s)
    if n == 1:
        return True
    pi = prefix_function(s)
    p = n - pi[-1]
    return not (n % p == 0 and n // p >= 2)

def solve():
    w = sys.stdin.readline().strip()
    n = len(w)

    # good[l][r] = whether w[l:r] is a good string
    good = [[False] * (n + 1) for _ in range(n)]

    # Compute goodness for every substring
    # O(n^3) worst-case, acceptable for moderate constraints typically used for this task
    for l in range(n):
        cur = []
        for r in range(l + 1, n + 1):
            cur.append(w[r - 1])
            s = ''.join(cur)
            good[l][r] = is_good_string(s)

    # dp[i] = minimum number of good strings to represent w[:i]
    # ways[i] = number of best representations for w[:i]
    INF = 10**9
    dp = [INF] * (n + 1)
    ways = [0] * (n + 1)
    dp[0] = 0
    ways[0] = 1

    for i in range(1, n + 1):
        for j in range(i):
            if good[j][i]:
                cand = dp[j] + 1
                if cand < dp[i]:
                    dp[i] = cand
                    ways[i] = ways[j]
                elif cand == dp[i]:
                    ways[i] = (ways[i] + ways[j]) % MOD

    print(dp[n], ways[n])

if __name__ == "__main__":
    solve()
